export function g10HistoryYearLessons(): LessonSeed[] {
  return G10_HISTORY_LESSONS.map((L) => ({
    title: L.title,
    description: L.description,
    objectives: L.objectives,
    content: L.content,
    order: L.order,
    durationMin: L.durationMin,
    sectionKey: L.sectionKey,
    questions: L.questions,
    topicMeta: {
      title: L.title,
      focus: L.description,
      keyIdeas: L.objectives.split("\n").map((s) => s.replace(/^•\s*/, "").trim()).filter(Boolean),
      practice: [
        { q: "Central aim of this lesson?", a: L.description },
        { q: "What should a strong solution include?", a: "A sourced claim with evidence and an honest limitation." },
      ],
    },
  }));
}

export function g10HistoryUnitLabel(sectionKey: string): string | null {
  const m = /^unit-(\d+)$/.exec(sectionKey);
  if (!m) return null;
  const n = Number(m[1]);
  const meta = G10_HISTORY_UNIT_META.find((u) => u.n === n);
  if (!meta) return null;
  return `Unit ${meta.n} of 10 · ${meta.title}`;
}
